        VALUES
        ('90050010-0000-4000-8000-000000000001', 'उपर्युक्त गद्यांश के आधार पर निम्नलिखित प्रश्नों के उत्तर दीजिए:
(क) साहित्य को समाज का मार्गदर्शक क्यों कहा गया है?
(ख) कबीर और प्रेमचंद जैसे साहित्यकारों का समाज सुधार में क्या योगदान रहा?
(ग) गद्यांश में आए ''विद्रूपता'' शब्द का अर्थ स्पष्ट कीजिए।', NULL, NULL, 'CASE', 'Hindi', 'अपठित गद्यांश', 5, '(क) साहित्य समाज की कमियों को उजागर करने के साथ-साथ सत्य, न्याय और मानवता का पथ प्रदर्शित करता है, इसलिए इसे मार्गदर्शक कहा गया है। (ख) उन्होंने सामाजिक रूढ़ियों, पाखंड और शोषण पर अपनी लेखनी से प्रहार कर जनमानस में चेतना और समानता के भाव जगाए। (ग) ''विद्रूपता'' का अर्थ है - विकृति, बुराई या सामाजिक विसंगति।', '2 अंक: मार्गदर्शक की सार्थकता; 2 अंक: कबीर व प्रेमचंद के योगदान की समीक्षा; 1 अंक: सटीक शब्दार्थ', 'साहित्य और समाज का संबंध अत्यंत अटूट है। साहित्य समाज का केवल दर्पण ही नहीं, बल्कि उसका मार्गदर्शक और नियामक भी है। जब-जब समाज में संकीर्णता, रूढ़िवादिता और शोषण का अंधकार गहराया है, तब-तब युगदृष्टा साहित्यकारों की लेखनी ने क्रांति का बिगुल फूँका है। कबीरदास, तुलसीदास, प्रेमचंद और निराला जैसे कालजयी रचनाकारों ने सामाजिक विद्रूपताओं पर तीखे प्रहार कर मानवीय मूल्यों, समता और बंधुत्व की प्रतिष्ठा की। जिस समाज का साहित्य निर्जीव और विलासितापूर्ण हो जाता है, वह समाज सांस्कृतिक रूप से पतन की ओर अग्रसर होता है।', NULL, 'MEDIUM', true),
        ('90050010-0000-4000-8000-000000000002', '''अपमान'' शब्द में किस उपसर्ग का प्रयोग हुआ है?', '{"A":"अ","B":"अप","C":"मान","D":"अति"}'::jsonb, 'B', 'MCQ', 'Hindi', 'उपसर्ग एवं प्रत्यय', 4, NULL, NULL, NULL, '''अपमान'' में ''अप'' (बुरा/विपरीत अर्थ वाला) उपसर्ग और ''मान'' मूल शब्द है।', 'MEDIUM', true),
        ('90050010-0000-4000-8000-000000000003', '''यथाशक्ति'' शब्द में कौन सा समास है?', '{"A":"अव्ययीभाव समास","B":"तत्पुरुष समास","C":"द्विगु समास","D":"द्वंद्व समास"}'::jsonb, 'A', 'MCQ', 'Hindi', 'समास', 4, NULL, NULL, NULL, 'जिस सामासिक पद का पूर्व पद अव्यय (यथा) हो और वही प्रधान हो, वहाँ अव्ययीभाव समास होता है (शक्ति के अनुसार)।', 'MEDIUM', true),
        ('90050010-0000-4000-8000-000000000004', 'काव्य खंड (क्षितिज - साखियाँ एवं सबद): ''मोकों कहाँ ढूँढे बंदे, मैं तो तेरे पास में। ना मैं देवल ना मैं मसजिद, ना काबे कैलास में।'' (क) कबीर के अनुसार ईश्वर का वास्तविक निवास कहाँ है? (ख) मनुष्य ईश्वर को किन बाह्य कर्मकांडों में व्यर्थ खोजता रहता है? (ग) कबीरदास जी ने बाह्य आडंबरों का खंडन किस प्रकार किया है?', NULL, NULL, 'SA', 'Hindi', 'साखियाँ एवं सबद', 5, '(क) कबीरदास जी के अनुसार ईश्वर किसी मंदिर, मस्जिद, काबा या कैलाश तीर्थ में नहीं, बल्कि प्रत्येक प्राणी के अंतःकरण (हृदय) की प्रत्येक श्वास में विद्यमान है। (ख) मनुष्य मूर्तिपूजा, तिलक, छापा, माला, तीर्थयात्रा, रोजा और विभिन्न ढोंग-आडंबरों में ईश्वर को खोजता रहता है। (ग) कबीर ने बाह्य कर्मकांडों, योग-वैराग्य और जाति-पाति के संकीर्ण भेदों को निरर्थक बताते हुए शुद्ध अंतःकरण और प्रेमपूर्ण सहज भक्ति पर बल दिया है।', '1.5 अंक: ईश्वर के अंतःकरण निवास की व्याख्या; 1.5 अंक: बाह्य तीर्थों/कर्मकांडों का उल्लेख; 2 अंक: कबीर के आडंबर-विरोधी दर्शन का विश्लेषण', NULL, NULL, 'MEDIUM', true),
        ('90050010-0000-4000-8000-000000000005', 'लघु उत्तरीय (क्षितिज): ''ल्हासा की ओर'' पाठ के आधार पर बताइए कि उस समय तिब्बत में हथियार का कानून न होने के कारण यात्रियों को किस प्रकार की कठिनाइयों और असुरक्षा का सामना करना पड़ता था?', NULL, NULL, 'SA', 'Hindi', 'ल्हासा की ओर', 5, 'उस समय तिब्बत में हथियार का कोई कानून नहीं था, इसलिए लोग पिस्तौल और बंदूक लाठियों की तरह खुलेआम लेकर घूमते थे। डाकुओं के लिए निर्जन घाटियाँ और डाँड़े आदर्श स्थान थे, जहाँ सरकार या पुलिस का कोई पहरा नहीं था। डाकू पहले सीधे आदमी को मार डालते थे और बाद में उसकी तलाशी लेते थे। इसी जान के खतरे से बचने के लिए लेखक राहुल सांकृत्यायन को भिखारी के छद्म वेश में यात्रा करनी पड़ी थी।', '1.5 अंक: हथियार कानून के अभाव और डाकुओं के आतंक का वर्णन; 1.5 अंक: लेखक के छद्म वेश धारण करने का औचित्य', NULL, NULL, 'MEDIUM', true),
        ('90050010-0000-4000-8000-000000000006', 'लघु उत्तरीय (कृतिका - रीढ़ की हड्डी): ''रीढ़ की हड्डी'' एकांकी के शीर्षक की सार्थकता स्पष्ट कीजिए। क्या यह शीर्षक समाज की संकीर्ण मानसिकता पर चोट करता है?', NULL, NULL, 'SA', 'Hindi', 'रीढ़ की हड्डी', 5, '''रीढ़ की हड्डी'' शीर्षक अत्यंत सार्थक, प्रतीकात्मक और व्यंग्यात्मक है। जिस प्रकार रीढ़ की हड्डी के बिना मानव शरीर सीधा खड़ा नहीं हो सकता, उसी प्रकार आत्मसम्मान, व्यक्तित्व और प्रगतिशील विचारों के बिना किसी समाज या व्यक्ति का नैतिक अस्तित्व नहीं हो सकता। एकांकी में शंकर शारीरिक रूप से तो झुका हुआ (बिना रीढ़ का) है ही, नैतिक रूप से भी चरित्रहीन और कायर है। साथ ही, यह शीर्षक उस पुरुष-प्रधान समाज की रीढ़विहीन संकीर्ण मानसिकता पर करारा प्रहार करता है जो कन्या की उच्च शिक्षा को छिपाने का ढोंग करता है।', '1.5 अंक: रीढ़ की हड्डी के प्रतीकात्मक अर्थ की व्याख्या; 1.5 अंक: शंकर के चरित्र व समाज की संकीर्ण सोच पर व्यंग्य का उद्घाटन', NULL, NULL, 'MEDIUM', true),
        ('90050010-0000-4000-8000-000000000007', 'दिए गए संकेत बिंदुओं के आधार पर ''समय का सदुपयोग'' विषय पर लगभग 100-120 शब्दों में एक सारगर्भित अनुच्छेद लिखिए। (संकेत बिंदु: समय का महत्व, बीता समय कभी वापस नहीं आता, सफलता की कुंजी, उपसंहार)', NULL, NULL, 'LA', 'Hindi', 'अनुच्छेद लेखन', 12, 'समय का सदुपयोग:
