        VALUES
        ('90050011-0000-4000-8000-000000000001', '(क) रहीम ने सच्चे मित्र की क्या पहचान बताई है?
(ख) आज के भौतिकवादी समाज में मित्रता के स्वरूप में क्या विकृति आई है?
(ग) ''सुमार्ग'' शब्द में उपसर्ग और मूल शब्द अलग कीजिए।', NULL, NULL, 'CASE', 'Hindi', 'अपठित गद्यांश', 5, '(क) रहीम के अनुसार जो व्यक्ति संकट और विपत्ति की कठिन घड़ी में साथ न छोड़े, वही सच्चा मित्र है। (ख) आज लोग निःस्वार्थ प्रेम के स्थान पर अपने स्वार्थ, धन और पद-प्रतिष्ठा को देखकर मित्रता करते हैं। (ग) सुमार्ग: उपसर्ग = ''सु'', मूल शब्द = ''मार्ग''।', '2 अंक: दोहे का भावार्थ; 2 अंक: आधुनिक मित्रता की समीक्षा; 1 अंक: सही उपसर्ग-मूल शब्द विच्छेद', 'सच्चा मित्र जीवन की सबसे बड़ी निधि है। एक सच्चा मित्र विपत्ति के समय ढाल बनकर खड़ा होता है और कुमार्ग से हटाकर सुमार्ग की ओर प्रेरित करता है। रहीम कवि ने कहा है - ''कहि रहीम संपति सगे, बनत बहुत बहु रीति। बिपति कसौटी जे कसे, तेई साँचे मीत॥'' आज के भौतिकतावादी युग में स्वार्थ सिद्धि के लिए मित्रता करने वालों की कमी नहीं है, परंतु जो बिना किसी प्रलोभन के केवल आत्मिक स्नेह के वशीभूत होकर सहयोग करे, वही सच्चा मित्र है।', NULL, 'MEDIUM', true),
        ('90050011-0000-4000-8000-000000000002', '''अपमान'' शब्द में किस उपसर्ग का प्रयोग हुआ है?', '{"A":"अ","B":"अप","C":"मान","D":"अति"}'::jsonb, 'B', 'MCQ', 'Hindi', 'उपसर्ग एवं प्रत्यय', 4, NULL, NULL, NULL, '''अपमान'' में ''अप'' (बुरा/विपरीत अर्थ वाला) उपसर्ग और ''मान'' मूल शब्द है।', 'MEDIUM', true),
        ('90050011-0000-4000-8000-000000000003', '''यथाशक्ति'' शब्द में कौन सा समास है?', '{"A":"अव्ययीभाव समास","B":"तत्पुरुष समास","C":"द्विगु समास","D":"द्वंद्व समास"}'::jsonb, 'A', 'MCQ', 'Hindi', 'समास', 4, NULL, NULL, NULL, 'जिस सामासिक पद का पूर्व पद अव्यय (यथा) हो और वही प्रधान हो, वहाँ अव्ययीभाव समास होता है (शक्ति के अनुसार)।', 'MEDIUM', true),
        ('90050011-0000-4000-8000-000000000004', 'लघु उत्तरीय (क्षितिज): ''ल्हासा की ओर'' पाठ के आधार पर बताइए कि उस समय तिब्बत में हथियार का कानून न होने के कारण यात्रियों को किस प्रकार की कठिनाइयों और असुरक्षा का सामना करना पड़ता था?', NULL, NULL, 'SA', 'Hindi', 'ल्हासा की ओर', 5, 'उस समय तिब्बत में हथियार का कोई कानून नहीं था, इसलिए लोग पिस्तौल और बंदूक लाठियों की तरह खुलेआम लेकर घूमते थे। डाकुओं के लिए निर्जन घाटियाँ और डाँड़े आदर्श स्थान थे, जहाँ सरकार या पुलिस का कोई पहरा नहीं था। डाकू पहले सीधे आदमी को मार डालते थे और बाद में उसकी तलाशी लेते थे। इसी जान के खतरे से बचने के लिए लेखक राहुल सांकृत्यायन को भिखारी के छद्म वेश में यात्रा करनी पड़ी थी।', '1.5 अंक: हथियार कानून के अभाव और डाकुओं के आतंक का वर्णन; 1.5 अंक: लेखक के छद्म वेश धारण करने का औचित्य', NULL, NULL, 'MEDIUM', true),
        ('90050011-0000-4000-8000-000000000005', 'लघु उत्तरीय (कृतिका - रीढ़ की हड्डी): ''रीढ़ की हड्डी'' एकांकी के शीर्षक की सार्थकता स्पष्ट कीजिए। क्या यह शीर्षक समाज की संकीर्ण मानसिकता पर चोट करता है?', NULL, NULL, 'SA', 'Hindi', 'रीढ़ की हड्डी', 5, '''रीढ़ की हड्डी'' शीर्षक अत्यंत सार्थक, प्रतीकात्मक और व्यंग्यात्मक है। जिस प्रकार रीढ़ की हड्डी के बिना मानव शरीर सीधा खड़ा नहीं हो सकता, उसी प्रकार आत्मसम्मान, व्यक्तित्व और प्रगतिशील विचारों के बिना किसी समाज या व्यक्ति का नैतिक अस्तित्व नहीं हो सकता। एकांकी में शंकर शारीरिक रूप से तो झुका हुआ (बिना रीढ़ का) है ही, नैतिक रूप से भी चरित्रहीन और कायर है। साथ ही, यह शीर्षक उस पुरुष-प्रधान समाज की रीढ़विहीन संकीर्ण मानसिकता पर करारा प्रहार करता है जो कन्या की उच्च शिक्षा को छिपाने का ढोंग करता है।', '1.5 अंक: रीढ़ की हड्डी के प्रतीकात्मक अर्थ की व्याख्या; 1.5 अंक: शंकर के चरित्र व समाज की संकीर्ण सोच पर व्यंग्य का उद्घाटन', NULL, NULL, 'MEDIUM', true),
        ('90050011-0000-4000-8000-000000000006', 'दीर्घ उत्तरीय (क्षितिज): ''प्रेमचंद के फटे जूते'' पाठ में हरिशंकर परसाई ने समाज की किस दिखावे की प्रवृत्ति पर व्यंग्य किया है? फटे जूते पहनकर भी प्रेमचंद के चेहरे पर निश्चिंतता और हँसी का क्या कारण था?', NULL, NULL, 'SA', 'Hindi', 'प्रेमचंद के फटे जूते', 5, 'हरिशंकर परसाई ने ''प्रेमचंद के फटे जूते'' के माध्यम से समाज में व्याप्त आडंबर, दिखावे और पाखंड की संस्कृति पर तीखा कटाक्ष किया है। आज का युग प्रदर्शनप्रियता का है जहाँ लोग दूसरों को प्रभावित करने के लिए किराए की पोशाक या इत्र लगाकर फोटो खिंचवाते हैं। इसके विपरीत, महान उपन्यास सम्राट प्रेमचंद भीतर और बाहर से बिल्कुल एक समान थे। उनके पैर का जूता फटा था और अँगूठा बाहर निकल रहा था, फिर भी उनके चेहरे पर एक बेपरवाह, निश्चिंत और व्यंग्यभरी मुस्कान थी। यह मुस्कान उन लोगों पर थी जो अपनी सामाजिक और चारित्रिक कमजोरियों को पर्दे के भीतर छिपाने के लिए दिन-रात समझौता करते हैं, जबकि प्रेमचंद ने जीवन भर किसी भी कुरीति या टीले से समझौता नहीं किया, बल्कि ठोकरें मारकर उसे ललकारा।', '2 अंक: आधुनिक दिखावे की संस्कृति का विश्लेषण; 2 अंक: प्रेमचंद के अंतर्बाह्य सामंजस्य का उद्घाटन; 2 अंक: चेहरे की व्यंग्यभरी मुस्कान का गूढ़ अर्थ', NULL, NULL, 'MEDIUM', true),
        ('90050011-0000-4000-8000-000000000007', 'अपने क्षेत्र में बढ़ती हुई चोरी और असामाजिक गतिविधियों की रोकथाम हेतु थानाध्यक्ष को लगभग 100 शब्दों में एक औपचारिक शिकायती पत्र लिखिए।', NULL, NULL, 'LA', 'Hindi', 'पत्र लेखन', 12, 'सेवा में,
