        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('90050013-0000-4000-8000-000000000001', '(क) रहीम ने सच्चे मित्र की क्या पहचान बताई है?
(ख) आज के भौतिकवादी समाज में मित्रता के स्वरूप में क्या विकृति आई है?
(ग) ''सुमार्ग'' शब्द में उपसर्ग और मूल शब्द अलग कीजिए।', NULL, NULL, 'CASE', 'Hindi', 'अपठित गद्यांश', 5, '(क) रहीम के अनुसार जो व्यक्ति संकट और विपत्ति की कठिन घड़ी में साथ न छोड़े, वही सच्चा मित्र है। (ख) आज लोग निःस्वार्थ प्रेम के स्थान पर अपने स्वार्थ, धन और पद-प्रतिष्ठा को देखकर मित्रता करते हैं। (ग) सुमार्ग: उपसर्ग = ''सु'', मूल शब्द = ''मार्ग''।', '2 अंक: दोहे का भावार्थ; 2 अंक: आधुनिक मित्रता की समीक्षा; 1 अंक: सही उपसर्ग-मूल शब्द विच्छेद', 'सच्चा मित्र जीवन की सबसे बड़ी निधि है। एक सच्चा मित्र विपत्ति के समय ढाल बनकर खड़ा होता है और कुमार्ग से हटाकर सुमार्ग की ओर प्रेरित करता है। रहीम कवि ने कहा है - ''कहि रहीम संपति सगे, बनत बहुत बहु रीति। बिपति कसौटी जे कसे, तेई साँचे मीत॥'' आज के भौतिकतावादी युग में स्वार्थ सिद्धि के लिए मित्रता करने वालों की कमी नहीं है, परंतु जो बिना किसी प्रलोभन के केवल आत्मिक स्नेह के वशीभूत होकर सहयोग करे, वही सच्चा मित्र है।', NULL, 'MEDIUM', true),
        ('90050013-0000-4000-8000-000000000002', '''अपमान'' शब्द में किस उपसर्ग का प्रयोग हुआ है?', '{"A":"अ","B":"अप","C":"मान","D":"अति"}'::jsonb, 'B', 'MCQ', 'Hindi', 'उपसर्ग एवं प्रत्यय', 4, NULL, NULL, NULL, '''अपमान'' में ''अप'' (बुरा/विपरीत अर्थ वाला) उपसर्ग और ''मान'' मूल शब्द है।', 'MEDIUM', true),
        ('90050013-0000-4000-8000-000000000003', '''यथाशक्ति'' शब्द में कौन सा समास है?', '{"A":"अव्ययीभाव समास","B":"तत्पुरुष समास","C":"द्विगु समास","D":"द्वंद्व समास"}'::jsonb, 'A', 'MCQ', 'Hindi', 'समास', 4, NULL, NULL, NULL, 'जिस सामासिक पद का पूर्व पद अव्यय (यथा) हो और वही प्रधान हो, वहाँ अव्ययीभाव समास होता है (शक्ति के अनुसार)।', 'MEDIUM', true),
        ('90050013-0000-4000-8000-000000000004', 'दीर्घ उत्तरीय (क्षितिज): ''प्रेमचंद के फटे जूते'' पाठ में हरिशंकर परसाई ने समाज की किस दिखावे की प्रवृत्ति पर व्यंग्य किया है? फटे जूते पहनकर भी प्रेमचंद के चेहरे पर निश्चिंतता और हँसी का क्या कारण था?', NULL, NULL, 'SA', 'Hindi', 'प्रेमचंद के फटे जूते', 5, 'हरिशंकर परसाई ने ''प्रेमचंद के फटे जूते'' के माध्यम से समाज में व्याप्त आडंबर, दिखावे और पाखंड की संस्कृति पर तीखा कटाक्ष किया है। आज का युग प्रदर्शनप्रियता का है जहाँ लोग दूसरों को प्रभावित करने के लिए किराए की पोशाक या इत्र लगाकर फोटो खिंचवाते हैं। इसके विपरीत, महान उपन्यास सम्राट प्रेमचंद भीतर और बाहर से बिल्कुल एक समान थे। उनके पैर का जूता फटा था और अँगूठा बाहर निकल रहा था, फिर भी उनके चेहरे पर एक बेपरवाह, निश्चिंत और व्यंग्यभरी मुस्कान थी। यह मुस्कान उन लोगों पर थी जो अपनी सामाजिक और चारित्रिक कमजोरियों को पर्दे के भीतर छिपाने के लिए दिन-रात समझौता करते हैं, जबकि प्रेमचंद ने जीवन भर किसी भी कुरीति या टीले से समझौता नहीं किया, बल्कि ठोकरें मारकर उसे ललकारा।', '2 अंक: आधुनिक दिखावे की संस्कृति का विश्लेषण; 2 अंक: प्रेमचंद के अंतर्बाह्य सामंजस्य का उद्घाटन; 2 अंक: चेहरे की व्यंग्यभरी मुस्कान का गूढ़ अर्थ', NULL, NULL, 'MEDIUM', true),
        ('90050013-0000-4000-8000-000000000005', 'पठित गद्यांश (क्षितिज - दो बैलों की कथा): ''झूरी काछी के दोनों बैलों के नाम थे—हीरा और मोती। दोनों पछाईं जाति के थे—देखने में सुंदर, काम में चौकस, डील में ऊँचे। बहुत दिनों साथ रहते-रहते दोनों में भाईचारा हो गया था। दोनों आमने-सामने या साथ बैठे हुए एक-दूसरे से मूक भाषा में विचार-विनिमय करते थे।'' (क) हीरा और मोती के शारीरिक गठन और स्वभाव की विशेषताएँ लिखिए। (ख) मूक भाषा में विचार-विनिमय से लेखक का क्या आशय है? (ग) प्रेमचंद ने पशुओं के इस भाईचारे के माध्यम से मानव समाज को क्या संदेश दिया है?', NULL, NULL, 'SA', 'Hindi', 'दो बैलों की कथा', 5, '(क) दोनों बैल पछाईं जाति के, दिखने में अत्यंत सुंदर, काम में चुस्त और ऊँचे डील-डौल वाले थे। (ख) वे बिना बोले अपनी आँखों, साँसों और स्नेह भरे व्यवहार से एक-दूसरे के मनोभावों को भली-भाँति समझ लेते थे। (ग) लेखक ने दर्शाया है कि प्रेम, अपनत्व और स्वतंत्रता की भावना केवल मनुष्यों में ही नहीं, बल्कि मूक पशुओं में भी विद्यमान होती है। आपसी एकता और भाईचारे से बड़े से बड़ा संकट जीता जा सकता है।', '1.5 अंक: बैलों की शारीरिक व स्वभावगत विशेषताएँ; 1.5 अंक: मूक भाषा का अर्थ; 2 अंक: एकता व बंधुत्व का मानवीय संदेश', NULL, NULL, 'MEDIUM', true),
        ('90050013-0000-4000-8000-000000000006', 'काव्य खंड (क्षितिज - साखियाँ एवं सबद): ''मोकों कहाँ ढूँढे बंदे, मैं तो तेरे पास में। ना मैं देवल ना मैं मसजिद, ना काबे कैलास में।'' (क) कबीर के अनुसार ईश्वर का वास्तविक निवास कहाँ है? (ख) मनुष्य ईश्वर को किन बाह्य कर्मकांडों में व्यर्थ खोजता रहता है? (ग) कबीरदास जी ने बाह्य आडंबरों का खंडन किस प्रकार किया है?', NULL, NULL, 'SA', 'Hindi', 'साखियाँ एवं सबद', 5, '(क) कबीरदास जी के अनुसार ईश्वर किसी मंदिर, मस्जिद, काबा या कैलाश तीर्थ में नहीं, बल्कि प्रत्येक प्राणी के अंतःकरण (हृदय) की प्रत्येक श्वास में विद्यमान है। (ख) मनुष्य मूर्तिपूजा, तिलक, छापा, माला, तीर्थयात्रा, रोजा और विभिन्न ढोंग-आडंबरों में ईश्वर को खोजता रहता है। (ग) कबीर ने बाह्य कर्मकांडों, योग-वैराग्य और जाति-पाति के संकीर्ण भेदों को निरर्थक बताते हुए शुद्ध अंतःकरण और प्रेमपूर्ण सहज भक्ति पर बल दिया है।', '1.5 अंक: ईश्वर के अंतःकरण निवास की व्याख्या; 1.5 अंक: बाह्य तीर्थों/कर्मकांडों का उल्लेख; 2 अंक: कबीर के आडंबर-विरोधी दर्शन का विश्लेषण', NULL, NULL, 'MEDIUM', true),
        ('90050013-0000-4000-8000-000000000007', 'अपने क्षेत्र में बढ़ती हुई चोरी और असामाजिक गतिविधियों की रोकथाम हेतु थानाध्यक्ष को लगभग 100 शब्दों में एक औपचारिक शिकायती पत्र लिखिए।', NULL, NULL, 'LA', 'Hindi', 'पत्र लेखन', 12, 'सेवा में,
