        ('9005001b-0000-4000-8000-000000000001', '''अपमान'' शब्द में किस उपसर्ग का प्रयोग हुआ है?', '{"A":"अ","B":"अप","C":"मान","D":"अति"}'::jsonb, 'B', 'MCQ', 'Hindi', 'उपसर्ग एवं प्रत्यय', 3, NULL, NULL, NULL, '''अपमान'' में ''अप'' (बुरा/विपरीत अर्थ वाला) उपसर्ग और ''मान'' मूल शब्द है।', 'MEDIUM', true),
        ('9005001b-0000-4000-8000-000000000002', '''यथाशक्ति'' शब्द में कौन सा समास है?', '{"A":"अव्ययीभाव समास","B":"तत्पुरुष समास","C":"द्विगु समास","D":"द्वंद्व समास"}'::jsonb, 'A', 'MCQ', 'Hindi', 'समास', 3, NULL, NULL, NULL, 'जिस सामासिक पद का पूर्व पद अव्यय (यथा) हो और वही प्रधान हो, वहाँ अव्ययीभाव समास होता है (शक्ति के अनुसार)।', 'MEDIUM', true),
        ('9005001b-0000-4000-8000-000000000003', 'लघु उत्तरीय (क्षितिज): ''ल्हासा की ओर'' पाठ के आधार पर बताइए कि उस समय तिब्बत में हथियार का कानून न होने के कारण यात्रियों को किस प्रकार की कठिनाइयों और असुरक्षा का सामना करना पड़ता था?', NULL, NULL, 'SA', 'Hindi', 'ल्हासा की ओर', 7, 'उस समय तिब्बत में हथियार का कोई कानून नहीं था, इसलिए लोग पिस्तौल और बंदूक लाठियों की तरह खुलेआम लेकर घूमते थे। डाकुओं के लिए निर्जन घाटियाँ और डाँड़े आदर्श स्थान थे, जहाँ सरकार या पुलिस का कोई पहरा नहीं था। डाकू पहले सीधे आदमी को मार डालते थे और बाद में उसकी तलाशी लेते थे। इसी जान के खतरे से बचने के लिए लेखक राहुल सांकृत्यायन को भिखारी के छद्म वेश में यात्रा करनी पड़ी थी।', '1.5 अंक: हथियार कानून के अभाव और डाकुओं के आतंक का वर्णन; 1.5 अंक: लेखक के छद्म वेश धारण करने का औचित्य', NULL, NULL, 'MEDIUM', true),
        ('9005001b-0000-4000-8000-000000000004', 'लघु उत्तरीय (कृतिका - रीढ़ की हड्डी): ''रीढ़ की हड्डी'' एकांकी के शीर्षक की सार्थकता स्पष्ट कीजिए। क्या यह शीर्षक समाज की संकीर्ण मानसिकता पर चोट करता है?', NULL, NULL, 'LA', 'Hindi', 'रीढ़ की हड्डी', 12, '''रीढ़ की हड्डी'' शीर्षक अत्यंत सार्थक, प्रतीकात्मक और व्यंग्यात्मक है। जिस प्रकार रीढ़ की हड्डी के बिना मानव शरीर सीधा खड़ा नहीं हो सकता, उसी प्रकार आत्मसम्मान, व्यक्तित्व और प्रगतिशील विचारों के बिना किसी समाज या व्यक्ति का नैतिक अस्तित्व नहीं हो सकता। एकांकी में शंकर शारीरिक रूप से तो झुका हुआ (बिना रीढ़ का) है ही, नैतिक रूप से भी चरित्रहीन और कायर है। साथ ही, यह शीर्षक उस पुरुष-प्रधान समाज की रीढ़विहीन संकीर्ण मानसिकता पर करारा प्रहार करता है जो कन्या की उच्च शिक्षा को छिपाने का ढोंग करता है।', '1.5 अंक: रीढ़ की हड्डी के प्रतीकात्मक अर्थ की व्याख्या; 1.5 अंक: शंकर के चरित्र व समाज की संकीर्ण सोच पर व्यंग्य का उद्घाटन', NULL, NULL, 'MEDIUM', true)
