        ('9005001c-0000-4000-8000-000000000001', '''अपमान'' शब्द में किस उपसर्ग का प्रयोग हुआ है?', '{"A":"अ","B":"अप","C":"मान","D":"अति"}'::jsonb, 'B', 'MCQ', 'Hindi', 'उपसर्ग एवं प्रत्यय', 3, NULL, NULL, NULL, '''अपमान'' में ''अप'' (बुरा/विपरीत अर्थ वाला) उपसर्ग और ''मान'' मूल शब्द है।', 'MEDIUM', true),
        ('9005001c-0000-4000-8000-000000000002', '''यथाशक्ति'' शब्द में कौन सा समास है?', '{"A":"अव्ययीभाव समास","B":"तत्पुरुष समास","C":"द्विगु समास","D":"द्वंद्व समास"}'::jsonb, 'A', 'MCQ', 'Hindi', 'समास', 3, NULL, NULL, NULL, 'जिस सामासिक पद का पूर्व पद अव्यय (यथा) हो और वही प्रधान हो, वहाँ अव्ययीभाव समास होता है (शक्ति के अनुसार)।', 'MEDIUM', true),
        ('9005001c-0000-4000-8000-000000000003', 'लघु उत्तरीय (कृतिका - रीढ़ की हड्डी): ''रीढ़ की हड्डी'' एकांकी के शीर्षक की सार्थकता स्पष्ट कीजिए। क्या यह शीर्षक समाज की संकीर्ण मानसिकता पर चोट करता है?', NULL, NULL, 'SA', 'Hindi', 'रीढ़ की हड्डी', 7, '''रीढ़ की हड्डी'' शीर्षक अत्यंत सार्थक, प्रतीकात्मक और व्यंग्यात्मक है। जिस प्रकार रीढ़ की हड्डी के बिना मानव शरीर सीधा खड़ा नहीं हो सकता, उसी प्रकार आत्मसम्मान, व्यक्तित्व और प्रगतिशील विचारों के बिना किसी समाज या व्यक्ति का नैतिक अस्तित्व नहीं हो सकता। एकांकी में शंकर शारीरिक रूप से तो झुका हुआ (बिना रीढ़ का) है ही, नैतिक रूप से भी चरित्रहीन और कायर है। साथ ही, यह शीर्षक उस पुरुष-प्रधान समाज की रीढ़विहीन संकीर्ण मानसिकता पर करारा प्रहार करता है जो कन्या की उच्च शिक्षा को छिपाने का ढोंग करता है।', '1.5 अंक: रीढ़ की हड्डी के प्रतीकात्मक अर्थ की व्याख्या; 1.5 अंक: शंकर के चरित्र व समाज की संकीर्ण सोच पर व्यंग्य का उद्घाटन', NULL, NULL, 'MEDIUM', true),
        ('9005001c-0000-4000-8000-000000000004', 'दीर्घ उत्तरीय (क्षितिज): ''प्रेमचंद के फटे जूते'' पाठ में हरिशंकर परसाई ने समाज की किस दिखावे की प्रवृत्ति पर व्यंग्य किया है? फटे जूते पहनकर भी प्रेमचंद के चेहरे पर निश्चिंतता और हँसी का क्या कारण था?', NULL, NULL, 'LA', 'Hindi', 'प्रेमचंद के फटे जूते', 12, 'हरिशंकर परसाई ने ''प्रेमचंद के फटे जूते'' के माध्यम से समाज में व्याप्त आडंबर, दिखावे और पाखंड की संस्कृति पर तीखा कटाक्ष किया है। आज का युग प्रदर्शनप्रियता का है जहाँ लोग दूसरों को प्रभावित करने के लिए किराए की पोशाक या इत्र लगाकर फोटो खिंचवाते हैं। इसके विपरीत, महान उपन्यास सम्राट प्रेमचंद भीतर और बाहर से बिल्कुल एक समान थे। उनके पैर का जूता फटा था और अँगूठा बाहर निकल रहा था, फिर भी उनके चेहरे पर एक बेपरवाह, निश्चिंत और व्यंग्यभरी मुस्कान थी। यह मुस्कान उन लोगों पर थी जो अपनी सामाजिक और चारित्रिक कमजोरियों को पर्दे के भीतर छिपाने के लिए दिन-रात समझौता करते हैं, जबकि प्रेमचंद ने जीवन भर किसी भी कुरीति या टीले से समझौता नहीं किया, बल्कि ठोकरें मारकर उसे ललकारा।', '2 अंक: आधुनिक दिखावे की संस्कृति का विश्लेषण; 2 अंक: प्रेमचंद के अंतर्बाह्य सामंजस्य का उद्घाटन; 2 अंक: चेहरे की व्यंग्यभरी मुस्कान का गूढ़ अर्थ', NULL, NULL, 'MEDIUM', true)
