        ('9005001e-0000-4000-8000-000000000002', '''यथाशक्ति'' शब्द में कौन सा समास है?', '{"A":"अव्ययीभाव समास","B":"तत्पुरुष समास","C":"द्विगु समास","D":"द्वंद्व समास"}'::jsonb, 'A', 'MCQ', 'Hindi', 'समास', 3, NULL, NULL, NULL, 'जिस सामासिक पद का पूर्व पद अव्यय (यथा) हो और वही प्रधान हो, वहाँ अव्ययीभाव समास होता है (शक्ति के अनुसार)।', 'MEDIUM', true),
        ('9005001e-0000-4000-8000-000000000003', 'पठित गद्यांश (क्षितिज - दो बैलों की कथा): ''झूरी काछी के दोनों बैलों के नाम थे—हीरा और मोती। दोनों पछाईं जाति के थे—देखने में सुंदर, काम में चौकस, डील में ऊँचे। बहुत दिनों साथ रहते-रहते दोनों में भाईचारा हो गया था। दोनों आमने-सामने या साथ बैठे हुए एक-दूसरे से मूक भाषा में विचार-विनिमय करते थे।'' (क) हीरा और मोती के शारीरिक गठन और स्वभाव की विशेषताएँ लिखिए। (ख) मूक भाषा में विचार-विनिमय से लेखक का क्या आशय है? (ग) प्रेमचंद ने पशुओं के इस भाईचारे के माध्यम से मानव समाज को क्या संदेश दिया है?', NULL, NULL, 'SA', 'Hindi', 'दो बैलों की कथा', 7, '(क) दोनों बैल पछाईं जाति के, दिखने में अत्यंत सुंदर, काम में चुस्त और ऊँचे डील-डौल वाले थे। (ख) वे बिना बोले अपनी आँखों, साँसों और स्नेह भरे व्यवहार से एक-दूसरे के मनोभावों को भली-भाँति समझ लेते थे। (ग) लेखक ने दर्शाया है कि प्रेम, अपनत्व और स्वतंत्रता की भावना केवल मनुष्यों में ही नहीं, बल्कि मूक पशुओं में भी विद्यमान होती है। आपसी एकता और भाईचारे से बड़े से बड़ा संकट जीता जा सकता है।', '1.5 अंक: बैलों की शारीरिक व स्वभावगत विशेषताएँ; 1.5 अंक: मूक भाषा का अर्थ; 2 अंक: एकता व बंधुत्व का मानवीय संदेश', NULL, NULL, 'MEDIUM', true),
        ('9005001e-0000-4000-8000-000000000004', 'काव्य खंड (क्षितिज - साखियाँ एवं सबद): ''मोकों कहाँ ढूँढे बंदे, मैं तो तेरे पास में। ना मैं देवल ना मैं मसजिद, ना काबे कैलास में।'' (क) कबीर के अनुसार ईश्वर का वास्तविक निवास कहाँ है? (ख) मनुष्य ईश्वर को किन बाह्य कर्मकांडों में व्यर्थ खोजता रहता है? (ग) कबीरदास जी ने बाह्य आडंबरों का खंडन किस प्रकार किया है?', NULL, NULL, 'LA', 'Hindi', 'साखियाँ एवं सबद', 12, '(क) कबीरदास जी के अनुसार ईश्वर किसी मंदिर, मस्जिद, काबा या कैलाश तीर्थ में नहीं, बल्कि प्रत्येक प्राणी के अंतःकरण (हृदय) की प्रत्येक श्वास में विद्यमान है। (ख) मनुष्य मूर्तिपूजा, तिलक, छापा, माला, तीर्थयात्रा, रोजा और विभिन्न ढोंग-आडंबरों में ईश्वर को खोजता रहता है। (ग) कबीर ने बाह्य कर्मकांडों, योग-वैराग्य और जाति-पाति के संकीर्ण भेदों को निरर्थक बताते हुए शुद्ध अंतःकरण और प्रेमपूर्ण सहज भक्ति पर बल दिया है।', '1.5 अंक: ईश्वर के अंतःकरण निवास की व्याख्या; 1.5 अंक: बाह्य तीर्थों/कर्मकांडों का उल्लेख; 2 अंक: कबीर के आडंबर-विरोधी दर्शन का विश्लेषण', NULL, NULL, 'MEDIUM', true)
