        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('9005001f-0000-4000-8000-000000000001', '''अपमान'' शब्द में किस उपसर्ग का प्रयोग हुआ है?', '{"A":"अ","B":"अप","C":"मान","D":"अति"}'::jsonb, 'B', 'MCQ', 'Hindi', 'उपसर्ग एवं प्रत्यय', 3, NULL, NULL, NULL, '''अपमान'' में ''अप'' (बुरा/विपरीत अर्थ वाला) उपसर्ग और ''मान'' मूल शब्द है।', 'MEDIUM', true),
        ('9005001f-0000-4000-8000-000000000002', '''यथाशक्ति'' शब्द में कौन सा समास है?', '{"A":"अव्ययीभाव समास","B":"तत्पुरुष समास","C":"द्विगु समास","D":"द्वंद्व समास"}'::jsonb, 'A', 'MCQ', 'Hindi', 'समास', 3, NULL, NULL, NULL, 'जिस सामासिक पद का पूर्व पद अव्यय (यथा) हो और वही प्रधान हो, वहाँ अव्ययीभाव समास होता है (शक्ति के अनुसार)।', 'MEDIUM', true),
        ('9005001f-0000-4000-8000-000000000003', 'काव्य खंड (क्षितिज - साखियाँ एवं सबद): ''मोकों कहाँ ढूँढे बंदे, मैं तो तेरे पास में। ना मैं देवल ना मैं मसजिद, ना काबे कैलास में।'' (क) कबीर के अनुसार ईश्वर का वास्तविक निवास कहाँ है? (ख) मनुष्य ईश्वर को किन बाह्य कर्मकांडों में व्यर्थ खोजता रहता है? (ग) कबीरदास जी ने बाह्य आडंबरों का खंडन किस प्रकार किया है?', NULL, NULL, 'SA', 'Hindi', 'साखियाँ एवं सबद', 7, '(क) कबीरदास जी के अनुसार ईश्वर किसी मंदिर, मस्जिद, काबा या कैलाश तीर्थ में नहीं, बल्कि प्रत्येक प्राणी के अंतःकरण (हृदय) की प्रत्येक श्वास में विद्यमान है। (ख) मनुष्य मूर्तिपूजा, तिलक, छापा, माला, तीर्थयात्रा, रोजा और विभिन्न ढोंग-आडंबरों में ईश्वर को खोजता रहता है। (ग) कबीर ने बाह्य कर्मकांडों, योग-वैराग्य और जाति-पाति के संकीर्ण भेदों को निरर्थक बताते हुए शुद्ध अंतःकरण और प्रेमपूर्ण सहज भक्ति पर बल दिया है।', '1.5 अंक: ईश्वर के अंतःकरण निवास की व्याख्या; 1.5 अंक: बाह्य तीर्थों/कर्मकांडों का उल्लेख; 2 अंक: कबीर के आडंबर-विरोधी दर्शन का विश्लेषण', NULL, NULL, 'MEDIUM', true),
        ('9005001f-0000-4000-8000-000000000004', 'लघु उत्तरीय (क्षितिज): ''ल्हासा की ओर'' पाठ के आधार पर बताइए कि उस समय तिब्बत में हथियार का कानून न होने के कारण यात्रियों को किस प्रकार की कठिनाइयों और असुरक्षा का सामना करना पड़ता था?', NULL, NULL, 'LA', 'Hindi', 'ल्हासा की ओर', 12, 'उस समय तिब्बत में हथियार का कोई कानून नहीं था, इसलिए लोग पिस्तौल और बंदूक लाठियों की तरह खुलेआम लेकर घूमते थे। डाकुओं के लिए निर्जन घाटियाँ और डाँड़े आदर्श स्थान थे, जहाँ सरकार या पुलिस का कोई पहरा नहीं था। डाकू पहले सीधे आदमी को मार डालते थे और बाद में उसकी तलाशी लेते थे। इसी जान के खतरे से बचने के लिए लेखक राहुल सांकृत्यायन को भिखारी के छद्म वेश में यात्रा करनी पड़ी थी।', '1.5 अंक: हथियार कानून के अभाव और डाकुओं के आतंक का वर्णन; 1.5 अंक: लेखक के छद्म वेश धारण करने का औचित्य', NULL, NULL, 'MEDIUM', true)
