-- V460: Seed 50 authentic CBSE Class 9 Hindi Mock Tests

DO $$
DECLARE
    v_class9_id UUID;
BEGIN
    SELECT id INTO v_class9_id FROM learn_exam_types WHERE slug IN ('class-9', 'cbse-class-9') LIMIT 1;
    IF v_class9_id IS NULL THEN
        SELECT id INTO v_class9_id FROM learn_exam_types WHERE name ILIKE '%Class 9%' LIMIT 1;
    END IF;

    IF v_class9_id IS NOT NULL THEN

        -- 1. Insert 50 Hindi Mock Tests
        ON CONFLICT (id) DO NOTHING;

        -- 2. Insert Authentic Questions and Link to Tests
        -- Questions for Test 1
समय संसार की सर्वाधिक मूल्यवान संपदा है। धन, पद और प्रतिष्ठा खोकर पुनः अर्जित किए जा सकते हैं, परंतु बीता हुआ एक क्षण भी किसी कीमत पर वापस नहीं लौटाया जा सकता। जो व्यक्ति समय का सम्मान करता है, समय उसे सफलता के सर्वोच्च शिखर पर पहुँचा देता है। प्रकृति भी हमें समयबद्धता का पाठ पढ़ाती है—सूर्य का उदय, ऋतु चक्र और दिन-रात का क्रम सब समय पर होता है। आलस्य समय का सबसे बड़ा शत्रु है। विद्यार्थी जीवन में तो समय प्रबंधन का महत्व और भी अधिक है, क्योंकि इसी काल में भविष्य की नींव रखी जाती है। अतः हमें प्रत्येक क्षण का सदुपयोग कर अपने लक्ष्य प्राप्ति में संलग्न रहना चाहिए।', '2 अंक: विषयवस्तु एवं संकेत बिंदुओं का समावेश; 2 अंक: भाषा-शैली एवं वर्तनी शुद्धता; 2 अंक: विचार प्रवाह एवं शब्द सीमा', NULL, NULL, 'MEDIUM', true),
        ('90050001-0000-4000-8000-00000000000d', 'अपने क्षेत्र में बढ़ती हुई चोरी और असामाजिक गतिविधियों की रोकथाम हेतु थानाध्यक्ष को लगभग 100 शब्दों में एक औपचारिक शिकायती पत्र लिखिए।', NULL, NULL, 'LA', 'Hindi', 'पत्र लेखन', 12, 'सेवा में,
थानाध्यक्ष महोदय,
नगर थाना, जनकपुरी, नई दिल्ली।

